mapper.select:
select DISTINCT COLUMN_NAME
from information_schema.`COLUMNS`
where Table_Name = #{tableName,jdbcType=VARCHAR}

mapper.delete:
delete from CHB_ASSETS_BASIS_DATA_CHILD
where  1=1
and DATA_SOURCE = '16'/*为避免误删除业务数据维护导入的数据，增加此条件*/

	and value_date = #{valueDate,jdbcType=DATE}


	and PROD_ID = #{prodId,jdbcType=VARCHAR}


	and ASSET_ID = #{assetId,jdbcType=VARCHAR}

mapper.insert:
insert into CHB_ASSETS_BASIS_DATA_CHILD(VAL_ID, PROD_ID, ASSET_ID, VALUE_DATE, MDATE, POS_AMT, TDY_COST_AMT, TDY_FLOAT_INGPL, TDY_INTINCEXP, DELAY_PAY_AMT, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_DEPT, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, STATUS, DATA_SOURCE,MD5PrimaryKey) select VAL_ID, PROD_ID, ASSET_ID, VALUE_DATE, MDATE, POS_AMT, TDY_COST_AMT, TDY_FLOAT_INGPL, TDY_INTINCEXP, DELAY_PAY_AMT, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_DEPT, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, STATUS, DATA_SOURCE,MD5PrimaryKey from ( select TEMP.* from (
SELECT #{item.valId,jdbcType=VARCHAR} VAL_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.assetId,jdbcType=VARCHAR} ASSET_ID, #{item.valueDate,jdbcType=DATE} VALUE_DATE, #{item.mdate,jdbcType=DATE} MDATE, #{item.posAmt,jdbcType=DECIMAL} POS_AMT, #{item.tdyCostAmt,jdbcType=DECIMAL} TDY_COST_AMT, #{item.tdyFloatIngpl,jdbcType=DECIMAL} TDY_FLOAT_INGPL, #{item.tdyIntincexp,jdbcType=DECIMAL} TDY_INTINCEXP, #{item.delayPayAmt,jdbcType=DECIMAL} DELAY_PAY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.status,jdbcType=VARCHAR} STATUS, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.md5primarykey,jdbcType=CHAR} MD5PRIMARYKEY FROM DUAL
) TEMP where not exists (select 1 from CHB_ASSETS_BASIS_DATA_CHILD CII where CII.PROD_ID = TEMP.PROD_ID AND CII.ASSET_ID = TEMP.ASSET_ID AND CII.VALUE_DATE = TEMP.VALUE_DATE) ) de ;
UPDATE CHB_ASSETS_BASIS_DATA_CHILD as A, ( select VAL_ID, MDATE, POS_AMT, TDY_COST_AMT, TDY_FLOAT_INGPL, TDY_INTINCEXP, DELAY_PAY_AMT, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_DEPT, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, STATUS, DATA_SOURCE, MD5PRIMARYKEY from ( select TEMP.* from (
SELECT #{item.valId,jdbcType=VARCHAR} VAL_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.assetId,jdbcType=VARCHAR} ASSET_ID, #{item.valueDate,jdbcType=DATE} VALUE_DATE, #{item.mdate,jdbcType=DATE} MDATE, #{item.posAmt,jdbcType=DECIMAL} POS_AMT, #{item.tdyCostAmt,jdbcType=DECIMAL} TDY_COST_AMT, #{item.tdyFloatIngpl,jdbcType=DECIMAL} TDY_FLOAT_INGPL, #{item.tdyIntincexp,jdbcType=DECIMAL} TDY_INTINCEXP, #{item.delayPayAmt,jdbcType=DECIMAL} DELAY_PAY_AMT, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.status,jdbcType=VARCHAR} STATUS, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.md5primarykey,jdbcType=CHAR} MD5PRIMARYKEY FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_ASSETS_BASIS_DATA_CHILD CII where CII.PROD_ID = TEMP.PROD_ID AND CII.ASSET_ID = TEMP.ASSET_ID AND CII.VALUE_DATE = TEMP.VALUE_DATE );

mapper.delete:
/*begin*/

	delete from CHB_ASSETS_BASIS_DATA_CHILD
	where ASSET_ID = #{item.assetId,jdbcType=VARCHAR}  and VALUE_DATE = #{item.valueDate,jdbcType=TIMESTAMP}
	and PROD_ID = #{item.prodId,jdbcType=VARCHAR}

;/*end;*/
